const $=id=>document.getElementById(id);let state=null,currentRoom=null,busy=false;
const remoteMode=!['127.0.0.1','localhost','[::1]'].includes(location.hostname),publicMode=false,tokenKey='rfd-central-tab-session';
if(new URLSearchParams(location.search).get('account')==='second'){sessionStorage.removeItem(tokenKey);history.replaceState(null,'',location.pathname);}
let token=sessionStorage.getItem(tokenKey)||'';
function notice(text){$('notice').textContent=window.rfdT?.(text)||text;$('notice').hidden=!text;}
async function api(route,body){const response=await fetch((remoteMode?'/realm/api/':'/api/')+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+(token||'logged-out'),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível concluir.');return data;}
async function action(fn){if(busy)return;busy=true;try{await fn();await refresh();}catch(e){notice(e.message);}finally{busy=false;}}
function credentials(){const values=new FormData($('login-form'));return {username:values.get('username'),password:values.get('password')};}
$('login-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{const result=await api('login',credentials());token=result.sessionToken;sessionStorage.setItem(tokenKey,token);$('login-form').reset();notice('Bem-vindo à comunidade.');});});
$('register').addEventListener('click',()=>{if($('login-form').reportValidity())action(async()=>{const result=await api('register',credentials());token=result.sessionToken;sessionStorage.setItem(tokenKey,token);$('login-form').reset();notice('Conta criada. Bem-vindo a Tristram.');});});
$('logout').addEventListener('click',()=>action(async()=>{await api('logout',{});state=null;token='';sessionStorage.removeItem(tokenKey);view('home');notice('Você saiu da conta.');}));
$('channel-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{await api('channel',{channel:new FormData(e.target).get('channel')});e.target.reset();});});
$('chat-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{await api('chat',{text:new FormData(e.target).get('text')});e.target.reset();});});
$('room-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{const values=new FormData(e.target);await api('rooms/create',{name:values.get('name'),password:values.get('password'),contentHash:state.contentHash});e.target.reset();$('create-dialog').close();notice('Partida criada no servidor.');});});
$('leave').addEventListener('click',()=>action(async()=>{await api('rooms/leave',{roomId:currentRoom.id});notice('Você saiu da sala.');}));
$('launch').addEventListener('click',()=>action(async()=>{const result=await api('launch',{roomId:currentRoom.id,windowedTest:$('test-window').checked});notice(result.message);if(result.launchUri&&/^rfd:\/\/play\/[A-Za-z0-9_-]+$/.test(result.launchUri))location.href=result.launchUri;}));
function element(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;}
async function refresh(){
  try{state=await api('state');}catch(e){signedOut();return;}
  $('entry').hidden=true;$('signed-in').hidden=false;$('public-entry').hidden=true;$('lobby').hidden=false;$('play-login').hidden=true;$('identity').textContent=state.username;$('welcome').textContent='Bem-vindo, '+state.username+'.';$('client-version').textContent=state.clientVersion?'v'+state.clientVersion:'Em preparação';$('chat-status').textContent=state.users.length+' no canal';$('chat-text').disabled=false;$('chat-form').querySelector('button').disabled=false;$('channel-title').textContent=state.channel||'Entrando no canal…';
  $('channels').replaceChildren(...state.channels.map(channel=>{const b=element('button',channel);b.setAttribute('aria-current',String(channel===state.channel));b.addEventListener('click',()=>action(()=>api('channel',{channel})));return b;}));
  $('users').replaceChildren(...state.users.map(user=>element('li',user)));
  const nearBottom=$('messages').scrollTop+$('messages').clientHeight>=$('messages').scrollHeight-45;
  $('messages').replaceChildren(...state.events.filter(e=>[4,5,7,10,13,18,19,23].includes(e.type)).map(e=>element('p',e.type===5?e.user+': '+e.text:e.type===4?'Mensagem privada de '+e.user+': '+e.text:e.text,e.type===5?'':'system')));if(nearBottom)$('messages').scrollTop=$('messages').scrollHeight;
  currentRoom=state.rooms.find(r=>r.players.some(p=>p.user.toLowerCase()===state.username.toLowerCase()));$('membership').hidden=!currentRoom;$('home-room').textContent=currentRoom?.name||'Nenhuma sala';$('room-count').textContent=state.rooms.length;$('show-create').disabled=!!currentRoom;
  if(currentRoom){$('room-name').textContent=currentRoom.name;$('party-slots').replaceChildren(...Array.from({length:4},(_,i)=>{const p=currentRoom.players[i],slot=element('div','','party-slot'+(p?'':' vacant'));slot.append(element('strong',p?p.user:'Lugar disponível'),element('small',p?(p.connected?'No jogo':'Na central'):'Aguardando aventureiro'));return slot;}));$('room-detail').textContent=currentRoom.name+' · '+currentRoom.players.length+'/4 · '+currentRoom.players.map(p=>p.user+(p.connected?' (cliente conectado)':'')).join(', ');$('launch').disabled=state.clientOpen||currentRoom.players.find(p=>p.user.toLowerCase()===state.username.toLowerCase())?.connected||false;}
  if(document.activeElement?.closest('#rooms')&&document.activeElement.tagName==='INPUT')return;
  $('rooms').replaceChildren(...state.rooms.map(room=>{const row=element('div','','room');const info=element('div','');info.append(element('strong',room.name),element('p',`${room.players.length}/4 · Campanha · Normal${room.locked?' · Com senha':''}`));row.append(info);const button=element('button',currentRoom?.id===room.id?'Sua sala':'Entrar →','secondary');button.disabled=!!currentRoom||room.players.length>=4;button.addEventListener('click',()=>{if(room.locked){notice('Informe a senha da sala para entrar.');const input=element('input','');input.type='password';input.maxLength=64;input.setAttribute('aria-label','Senha para '+room.name);const confirm=element('button','Confirmar entrada');confirm.addEventListener('click',()=>action(()=>api('rooms/join',{roomId:room.id,password:input.value,contentHash:state.contentHash})));row.append(input,confirm);input.focus();}else action(()=>api('rooms/join',{roomId:room.id,contentHash:state.contentHash}));});row.append(button);return row;}));if(!state.rooms.length)$('rooms').append(element('p','Nenhuma partida aberta. Crie a primeira jornada.','muted'));
}
signedOut();view(location.hash.slice(1)||'home');refresh();refreshHealth();setInterval(()=>{if(!busy&&!document.hidden)refresh();},1500);

function view(name){if(!['home','play','social','client'].includes(name))name='home';document.querySelectorAll('[data-panel]').forEach(el=>el.hidden=el.dataset.panel!==name);document.querySelectorAll('[data-view]').forEach(el=>{const on=el.dataset.view===name;el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});history.replaceState(null,'',location.pathname+'#'+name);}
document.querySelectorAll('[data-view],[data-go]').forEach(el=>el.addEventListener('click',()=>view(el.dataset.view||el.dataset.go)));
for(const id of ['hero-play','continue-play'])$(id).addEventListener('click',()=>{if(state)view('play');else if(publicMode)location.href='http://127.0.0.1:18092/';else{view('home');$('login-form').elements.username.focus();}});
$('account-nav').addEventListener('click',()=>{view('home');if(!state&&!publicMode)$('login-form').elements.username.focus();});
for(const id of ['second-account','second-account-client'])$(id).addEventListener('click',()=>{window.open((publicMode?'http://127.0.0.1:18092':location.origin)+'/?account=second','_blank','noopener');});
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>$(el.dataset.close).close()));
$('show-create').addEventListener('click',()=>{if(!state){notice('Entre na sua conta para criar uma sala.');view('home');return;}if(!currentRoom)$('create-dialog').showModal();});
$('refresh-rooms').addEventListener('click',()=>action(async()=>{await refresh();notice('Salas atualizadas.');}));
function signedOut(){state=null;currentRoom=null;$('entry').hidden=publicMode;$('signed-in').hidden=true;$('public-entry').hidden=!publicMode;$('lobby').hidden=true;$('play-login').hidden=false;$('identity').textContent='Minha conta';$('show-create').disabled=false;$('chat-text').disabled=true;$('chat-form').querySelector('button').disabled=true;$('channels').replaceChildren();$('users').replaceChildren();$('messages').replaceChildren(element('p','Entre na sua conta para participar do bate-papo.','system'));}
async function refreshHealth(){if(publicMode){$('connection-text').textContent='Prévia da comunidade';$('realm-status').textContent='Servidor público em preparação';$('footer-status').textContent='Abra a central local para jogar';return;}try{const res=await fetch(remoteMode?'/realm/health':'/health');if(!res.ok)throw Error();const h=await res.json();$('connection-dot').classList.toggle('online',h.gatewayListening);$('connection-text').textContent=h.gatewayListening?(remoteMode?'Reino online':'Servidor local online'):'Servidor indisponível';$('realm-status').textContent=h.gatewayListening?'Tristram está à sua espera.':'O reino está offline.';$('stat-users').textContent=h.lobbySessions;$('stat-rooms').textContent=h.rooms;$('stat-playing').textContent=h.connectedGamePlayers;$('footer-status').textContent=(remoteMode?'REINO ONLINE · ATÉ ':'REINO LOCAL · ATÉ ')+h.playersPerRoom+' JOGADORES POR SALA';}catch{$('connection-dot').classList.remove('online');$('connection-text').textContent='Servidor indisponível';$('realm-status').textContent='Aguardando o servidor.';$('footer-status').textContent='CONEXÃO INTERROMPIDA';for(const id of ['stat-users','stat-rooms','stat-playing'])$(id).textContent='—';}}
setInterval(()=>{if(!document.hidden)refreshHealth();},5000);
